function get(platform) return profiles[platform] or {} end
function option_names() local names = table.keys(descriptors); table.sort(names); return names end
function is_boolean(name) return descriptors[name] and descriptors[name].kind == "boolean" end
function normalize(options, defaults, enabled)
    for key, value in pairs(options) do
        local descriptor = descriptors[key]
        if type(defaults[key]) == "boolean" or (descriptor and descriptor.kind == "boolean") or key:match("^module_.+_enabled$") then
            options[key] = enabled(value)
        elseif descriptor and descriptor.kind == "number" then
            local number = tonumber(value)
            assert(number and number >= 1 and number % 1 == 0, "Invalid positive integer option: " .. key)
            options[key] = number
        elseif descriptor and #descriptor.values > 0 then
            assert(type(value) == "string" and table.contains(descriptor.values, value:lower()), "Invalid platform enum option: " .. key)
            options[key] = value:lower()
        end
    end
end
